<template><section class="banner-manager"><header><div><div class="section-kicker">首页内容运营</div><h3>轮播横幅</h3><p>设置门店学习入口，让新标准与重点教案更容易被看到。</p></div><el-button type="primary" :icon="Plus" @click="edit()">新增横幅</el-button></header><div class="banner-guide"><el-icon><InfoFilled /></el-icon><span>建议比例 5:2（1200 × 480 px） · 最多启用 5 张 · 仅向有阅读权限的员工展示</span></div><el-table :data="banners" class="banner-table"><el-table-column label="横幅内容" min-width="240"><template #default="{row}"><div class="banner-name"><div class="banner-symbol"><el-icon><Picture /></el-icon></div><div><strong>{{row.title}}</strong><p>{{row.subtitle||'未填写简介'}}</p></div></div></template></el-table-column><el-table-column label="点击跳转" min-width="180"><template #default="{row}"><span class="destination">{{entries.find(e=>e.id===row.entry_id)?.title||'学习专区列表'}}</span></template></el-table-column><el-table-column label="展示状态" width="100"><template #default="{row}"><span class="banner-status" :class="{enabled:row.enabled}"><i/>{{row.enabled?'展示中':'已停用'}}</span></template></el-table-column><el-table-column prop="sort_order" label="排序" width="64"/><el-table-column label="操作" width="75"><template #default="{row}"><el-button link type="primary" @click="edit(row)">编辑</el-button></template></el-table-column><template #empty><div class="banner-empty"><el-icon><Picture /></el-icon><h4>还没有轮播横幅</h4><p>上传一张图片，为门店推荐重要通知或学习资料。</p><el-button :icon="Plus" @click="edit()">创建第一张横幅</el-button></div></template></el-table></section>
<el-dialog class="banner-dialog" v-model="opened" :title="form.id?'编辑轮播横幅':'新增轮播横幅'" width="min(720px,96vw)" :close-on-click-modal="false"><el-form label-position="top"><el-form-item label="横幅图片"><div class="banner-upload" @dragover.prevent @drop.prevent="upload($event.dataTransfer.files[0])"><img v-if="image" :src="image" alt="横幅预览"/><input ref="input" type="file" hidden accept="image/png,image/jpeg,image/webp" @change="upload($event.target.files[0]);$event.target.value=''"/><el-button :loading="busy" @click="input?.click()">{{form.file_id?'更换图片':'点击或拖入图片上传'}}</el-button><p>JPG / PNG / WebP，单张最多 5MB。完整保留原图，小程序读取轻量预览。</p></div></el-form-item><el-form-item label="标题"><el-input v-model="form.title" maxlength="60" placeholder="例如：收银机操作指南"/></el-form-item><el-form-item label="简介"><el-input v-model="form.subtitle" maxlength="120" placeholder="可不填"/></el-form-item><el-form-item label="点击后进入"><el-select v-model="form.entry_id" clearable filterable placeholder="学习专区列表"><el-option v-for="entry in entries.filter(e=>e.status==='published')" :key="entry.id" :label="entry.title" :value="entry.id"/></el-select><p class="hint">选择资料后，仅向有该资料阅读权限的员工展示。</p></el-form-item><el-form-item label="适用门店"><el-radio-group v-model="form.mode"><el-radio-button value="all">全部门店</el-radio-button><el-radio-button value="stores">指定门店</el-radio-button></el-radio-group><StoreRegionSelect v-if="form.mode==='stores'" v-model="form.store_ids" :stores="stores" multiple restrict-to-stores/></el-form-item><div class="settings"><el-form-item label="展示顺序"><el-input-number v-model="form.sort_order" :min="0" :max="999"/></el-form-item><el-form-item label="是否展示"><el-switch v-model="form.enabled" :disabled="!canPublish"/></el-form-item></div></el-form><template #footer><el-button :disabled="busy" @click="opened=false">取消</el-button><el-button type="primary" :loading="busy" @click="save">保存横幅</el-button></template></el-dialog></template>
<script setup>
import {ref,onMounted,onBeforeUnmount} from 'vue'
import {ElMessage} from 'element-plus'
import {Plus,Picture,InfoFilled} from '@element-plus/icons-vue'
import {knowledgeApi as api} from '@/api'
import StoreRegionSelect from './StoreRegionSelect.vue'
const props=defineProps({entries:Array,stores:Array,canPublish:Boolean}),banners=ref([]),opened=ref(false),form=ref({}),image=ref(''),input=ref(null),busy=ref(false)
let blob
const clean=()=>{if(blob)URL.revokeObjectURL(blob);blob=null;image.value=''}
async function load(){try{banners.value=(await api.banners()).rows}catch(e){ElMessage.error(e.message)}}
async function edit(row){clean();form.value=row?JSON.parse(JSON.stringify(row)):{title:'',subtitle:'',file_id:null,entry_id:null,enabled:false,sort_order:0,mode:'all',store_ids:[]};opened.value=true;if(row){try{const chunks=[];let total=1;for(let i=0;i<total;i++){const r=await api.chunk(row.file_id,i);total=r.total;const raw=atob(r.chunk);chunks.push(Uint8Array.from(raw,c=>c.charCodeAt(0)))}blob=URL.createObjectURL(new Blob(chunks));image.value=blob}catch(e){ElMessage.error(e.message)}}}
async function upload(file){if(!file||busy.value)return;if(!['image/jpeg','image/png','image/webp'].includes(file.type)||file.size>5*1024*1024){ElMessage.warning('请选择5MB以内的JPG、PNG或WebP图片');return}busy.value=true;try{const r=await api.upload(file,()=>{});form.value.file_id=r.file.id;clean();blob=URL.createObjectURL(file);image.value=blob;if(!form.value.title)form.value.title=file.name.replace(/\.[^.]+$/,'')}catch(e){ElMessage.error(e.message)}finally{busy.value=false}}
async function save(){if(busy.value)return;busy.value=true;try{await api.saveBanner(form.value);opened.value=false;await load();ElMessage.success('横幅已保存')}catch(e){ElMessage.error(e.message)}finally{busy.value=false}}
onMounted(load);onBeforeUnmount(clean)
</script>
<style scoped>
.banner-manager{background:var(--el-bg-color,#fff);border:1px solid #e6ebf3;border-radius:12px;overflow:hidden}.banner-manager header{display:flex;align-items:center;justify-content:space-between;gap:20px;padding:24px}.section-kicker{color:#9aa7b7;font-size:11px;margin-bottom:7px}.banner-manager h3{margin:0;font-size:20px;font-weight:600;color:#334962}.banner-manager header p{color:#8594a8;font-size:12px;line-height:1.7;margin:8px 0 0}.banner-guide{margin:0 24px 24px;display:flex;gap:8px;align-items:center;background:#f6f9fe;border:1px solid #e8eef9;border-radius:8px;padding:12px;color:#7b8ca5;font-size:11px;line-height:1.8}.banner-guide>.el-icon{font-size:16px;flex-shrink:0}.banner-table{--el-table-header-bg-color:#f7f9fc;--el-table-header-text-color:#8a97a8;--el-table-border-color:#edf0f5;font-size:12px}.banner-table :deep(th.el-table__cell){font-size:11px;font-weight:500;height:42px}.banner-table :deep(td.el-table__cell){padding:18px 0}.banner-table :deep(.cell){padding:0 18px}.banner-name{display:flex;gap:12px;align-items:center}.banner-symbol{width:56px;height:36px;background:#eef3fb;border:1px solid #e1e9f6;border-radius:6px;display:grid;place-items:center;flex-shrink:0;color:#809ac0}.banner-symbol .el-icon{font-size:22px}.banner-name strong{font-size:13px;font-weight:500;color:#465d78;overflow-wrap:anywhere}.banner-name p{font-size:11px;color:#99a5b5;margin:5px 0 0;line-height:1.6}.destination{font-size:12px;color:#687c95}.banner-status{display:flex;align-items:center;gap:6px;color:#8b99ab;font-size:11px}.banner-status i{width:6px;height:6px;background:#b8c2d0;border-radius:50%}.banner-status.enabled{color:#4c9375}.banner-status.enabled i{background:#5aa783}.banner-empty{padding:48px 20px;line-height:1.6}.banner-empty>.el-icon{font-size:34px;color:#a4b5ce}.banner-empty h4{font-weight:500;font-size:14px;color:#61758f;margin:14px 0 6px}.banner-empty p{font-size:12px;color:#9ba8b8;margin:0 0 20px;white-space:normal}.banner-dialog{--el-dialog-border-radius:14px;--el-dialog-padding-primary:24px}.banner-dialog :deep(.el-dialog__header){padding-bottom:20px;border-bottom:1px solid #edf0f5}.banner-dialog :deep(.el-dialog__body){padding-top:22px}.banner-dialog :deep(.el-dialog__title){font-size:18px;font-weight:600;color:#354b66}.banner-dialog :deep(.el-form-item__label){font-size:12px;color:#73859b}.banner-dialog :deep(.el-dialog__footer){border-top:1px solid #edf0f5;margin-top:20px;padding-top:20px}.banner-upload{width:100%;border:1.5px dashed #cdd9ea;padding:20px;border-radius:10px;text-align:center;box-sizing:border-box;background:#fafcfe}.banner-upload img{display:block;width:100%;height:190px;object-fit:contain;background:#f1f5fb;border-radius:7px;margin-bottom:16px}.banner-upload p,.hint{font-size:11px;color:#91a0b4;line-height:1.8;margin:10px 0 0}.settings{display:flex;gap:48px;padding:16px 20px 0;background:#f7f9fc;border:1px solid #e9eef5;border-radius:8px}.el-select{width:100%}.banner-dialog :deep(.el-radio-group){margin-bottom:12px}@media(max-width:600px){.banner-manager header{padding:18px;align-items:flex-start;flex-direction:column;gap:14px}.banner-guide{margin:0 18px 18px}.banner-table :deep(.cell){padding:0 10px}.settings{gap:20px}.banner-upload{padding:12px}.banner-upload img{height:140px}}
</style>
